/**
 * Pure, dependency-free payment & pricing guards shared by server.ts and the regression tests.
 * Nothing here touches the network or the database.
 */
import crypto from 'node:crypto';

export type OrderKind = 'booking' | 'survey' | 'extension' | 'unknown';

const ORDER_ID_PATTERN = /^(BOOK|BOOKING|SRV|EXT|EXTEND)-[A-Za-z0-9_-]{3,80}$/;

/** Order ids are generated by this app; anything else must never reach Midtrans or the database. */
export function isValidOrderId(orderId: unknown): orderId is string {
  return typeof orderId === 'string' && ORDER_ID_PATTERN.test(orderId);
}

export function classifyOrderId(orderId: string): OrderKind {
  if (orderId.startsWith('BOOK-') || orderId.startsWith('BOOKING-')) return 'booking';
  if (orderId.startsWith('SRV-')) return 'survey';
  if (orderId.startsWith('EXT-') || orderId.startsWith('EXTEND-')) return 'extension';
  return 'unknown';
}

/** Midtrans signature_key = SHA512(order_id + status_code + gross_amount + server_key). */
export function computeMidtransSignature(orderId: string, statusCode: string, grossAmount: string, serverKey: string): string {
  return crypto.createHash('sha512').update(orderId + statusCode + grossAmount + serverKey).digest('hex');
}

/**
 * Fail-closed verification: returns false when the server key is missing, the signature is missing,
 * or the signature differs (constant-time comparison).
 */
export function verifyMidtransSignature(
  notification: { order_id?: string; status_code?: string; gross_amount?: string; signature_key?: string },
  serverKey: string
): boolean {
  if (!serverKey || serverKey === 'YOUR_MIDTRANS_SERVER_KEY_HERE') return false;
  if (!notification?.signature_key || !notification.order_id) return false;
  const expected = Buffer.from(
    computeMidtransSignature(notification.order_id, String(notification.status_code ?? ''), String(notification.gross_amount ?? ''), serverKey)
  );
  const received = Buffer.from(String(notification.signature_key));
  return expected.length === received.length && crypto.timingSafeEqual(expected, received);
}

/** Idempotency key: Midtrans reuses transaction_id for pending -> settlement, so the status must be part of the key. */
export function webhookEventKey(n: { transaction_id?: string; order_id?: string; transaction_status?: string; fraud_status?: string; status_code?: string }): string {
  return `${n.transaction_id || n.order_id}:${n.transaction_status}:${n.fraud_status || ''}:${n.status_code || ''}`;
}

/** Paid amount must equal the expected amount (Rupiah, tolerance < 1). */
export function amountsMatch(expected: number, paid: number): boolean {
  return Number.isFinite(expected) && Number.isFinite(paid) && expected > 0 && Math.abs(expected - paid) < 1;
}

/** Contract extension total is always months x monthly rate; months must be an integer in [1, 24]. */
export function computeExtensionTotal(months: unknown, monthlyRate: unknown): number | null {
  const m = Math.floor(Number(months));
  const r = Number(monthlyRate);
  if (!Number.isFinite(m) || m < 1 || m > 24 || !Number.isFinite(r) || r <= 0) return null;
  return m * r;
}

export interface ServerCheckoutPricingInput {
  checkoutType: 'monthly' | 'daily' | 'survey';
  roomPriceMonthly: number;
  roomPriceDaily: number;
  isDailyEnabled?: boolean;
  durationMonths?: number;
  durationDays?: number;
  depositAmount?: number;
  surveyDpAmount?: number;
  isWithoutDp?: boolean;
  coupon?: {
    code: string;
    discount_type: 'percentage' | 'fixed';
    discount_value: number;
    min_duration_months?: number | null;
    min_duration_days?: number | null;
    max_discount_amount?: number | null;
    is_active: boolean;
  } | null;
}

export interface ServerCheckoutPricingResult {
  rentBase: number;
  discount: number;
  deposit: number;
  totalPrice: number;
  appliedCouponCode: string | null;
}

/**
 * Pure server-side checkout pricing engine (R-01).
 * Never trusts client-provided prices or discounts.
 */
export function computeServerCheckoutPrice(input: ServerCheckoutPricingInput): ServerCheckoutPricingResult {
  if (input.checkoutType === 'survey') {
    if (input.isWithoutDp) {
      return {
        rentBase: 0,
        discount: 0,
        deposit: 0,
        totalPrice: 0,
        appliedCouponCode: null
      };
    }
    const dp = Number(input.surveyDpAmount);
    const validDp = Number.isFinite(dp) && dp > 0 ? Math.round(dp) : 500000;
    return {
      rentBase: 0,
      discount: 0,
      deposit: validDp,
      totalPrice: validDp,
      appliedCouponCode: null
    };
  }

  const isDaily = input.checkoutType === 'daily';
  if (isDaily) {
    const days = Math.floor(Number(input.durationDays ?? 1));
    if (!Number.isFinite(days) || days < 1 || days > 365) {
      throw new Error('Durasi sewa harian harus antara 1 sampai 365 hari.');
    }
    const dailyRate = Number(input.roomPriceDaily);
    if (!Number.isFinite(dailyRate) || dailyRate <= 0) {
      throw new Error('Harga sewa harian kamar tidak valid atau belum dikonfigurasi.');
    }
    const rentBase = Math.round(dailyRate * days);
    let discount = 0;
    let appliedCouponCode: string | null = null;

    if (input.coupon && input.coupon.is_active) {
      const minDays = Number(input.coupon.min_duration_days || 0);
      if (minDays <= 0 || days >= minDays) {
        if (input.coupon.discount_type === 'percentage') {
          const pct = Math.max(0, Math.min(100, Number(input.coupon.discount_value || 0)));
          discount = Math.round(rentBase * (pct / 100));
          const maxCap = Number(input.coupon.max_discount_amount || 0);
          if (maxCap > 0 && discount > maxCap) {
            discount = Math.round(maxCap);
          }
        } else {
          discount = Math.round(Math.max(0, Number(input.coupon.discount_value || 0)));
        }
        discount = Math.min(discount, rentBase);
        if (discount > 0) {
          appliedCouponCode = input.coupon.code;
        }
      }
    }

    const totalPrice = Math.max(0, rentBase - discount);
    return {
      rentBase,
      discount,
      deposit: 0,
      totalPrice,
      appliedCouponCode
    };
  }

  // Monthly booking
  const months = Math.floor(Number(input.durationMonths ?? 1));
  if (!Number.isFinite(months) || months < 1 || months > 24) {
    throw new Error('Durasi sewa bulanan harus antara 1 sampai 24 bulan.');
  }
  const monthlyRate = Number(input.roomPriceMonthly);
  if (!Number.isFinite(monthlyRate) || monthlyRate <= 0) {
    throw new Error('Harga sewa bulanan kamar tidak valid.');
  }
  const rentBase = Math.round(monthlyRate * months);
  const rawDeposit = Number(input.depositAmount);
  const deposit = Number.isFinite(rawDeposit) && rawDeposit >= 0 ? Math.round(rawDeposit) : 500000;

  let discount = 0;
  let appliedCouponCode: string | null = null;

  if (input.coupon && input.coupon.is_active) {
    const minMonths = Number(input.coupon.min_duration_months || 0);
    if (minMonths <= 0 || months >= minMonths) {
      if (input.coupon.discount_type === 'percentage') {
        const pct = Math.max(0, Math.min(100, Number(input.coupon.discount_value || 0)));
        discount = Math.round(rentBase * (pct / 100));
        const maxCap = Number(input.coupon.max_discount_amount || 0);
        if (maxCap > 0 && discount > maxCap) {
          discount = Math.round(maxCap);
        }
      } else {
        discount = Math.round(Math.max(0, Number(input.coupon.discount_value || 0)));
      }
      discount = Math.min(discount, rentBase);
      if (discount > 0) {
        appliedCouponCode = input.coupon.code;
      }
    }
  }

  const totalPrice = Math.max(0, rentBase - discount + deposit);
  return {
    rentBase,
    discount,
    deposit,
    totalPrice,
    appliedCouponCode
  };
}
